const bounceSenderRx = /(mailer-daemon|postmaster|mail delivery subsystem)/i;
const bounceTextRx = /(address not found|recipient address rejected|undeliverable|delivery status notification|delivery has failed|550\s|5\.1\.1|5\.4\.1)/i;
const emailRx = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;

return items.flatMap((item) => {
  const j = item.json || {};

  const from = String(
    j.from ||
    j.sender ||
    j.headers?.from ||
    ""
  );

  const subject = String(j.subject || "");

  const text = String(
    j.textPlain ||
    j.snippet ||
    j.text ||
    j.html ||
    ""
  );

  const all = [
    from,
    subject,
    text
  ].join("\n");

  const isBounce =
    bounceSenderRx.test(from) ||
    bounceTextRx.test(all);

  if (!isBounce) {
    return [];
  }

  const emails = [
    ...new Set(
      (all.match(emailRx) || []).map((x) => x.toLowerCase())
    )
  ];

  const systemDomains = [
    "google.com",
    "gmail.com",
    "googlemail.com",
    "outlook.com",
    "microsoft.com"
  ];

  const recipient =
    emails.find(
      (e) => !systemDomains.some((d) => e.endsWith("@" + d))
    ) ||
    emails[0] ||
    "";

  const codeMatch = all.match(
    /(?:550\s[^\n]*|5\.[0-9]\.[0-9])/i
  );

  const code = codeMatch ? codeMatch[0] : "";

  return [
    {
      json: {
        event: "bounce",
        bounced: true,
        bounced_email: recipient,
        bounce_code: code,
        bounce_subject: subject,
        bounce_reason: (text || subject).slice(0, 500),
        safe_to_outreach: false,
        email_status: "Bounced",
        stop_followups: true,
        detected_at: new Date().toISOString(),
        gmail_message_id: j.id || j.messageId || ""
      }
    }
  ];
});
